export type MessagePage = {
	items: TimelineMessage[],
	next_cursor: string | null,
};

export type MessagePartView = { type: "text"; text: string } | { type: "media"; asset: AssetRef; role: MediaRole };

export type MessagePinRequest = {
	conversation_id: string,
	message_id: string,
	expected_revision: number,
	pinned: boolean,
	client_operation_id: string,
};

export type MessageRevisionPage = {
	items: MessageRevisionView[],
	next_cursor: string | null,
};

/**  One saved version of a message's content, oldest first. */
export type MessageRevisionView = {
	id: string,
	sequence: number,
	parts: MessagePartView[],
	reasoning: string | null,
	authored_at: number,
	/**  The reply variant this edit rewrote. */
	supersedes_candidate_id: string | null,
};

export type MessageRole = "user" | "assistant" | "system" | "scene";

/**
 *  Switches a one-to-one chat's starting scene from its scene message: the
 *  chat's scene setting and the message's text both change.
 */
export type MessageSceneSelectRequest = {
	conversation_id: string,
	message_id: string,
	expected_revision: number,
	scene_id: string,
	client_operation_id: string,
};

/**
 *  Visible messages in conversation order, oldest first. `before_cursor`
 *  continues with older messages and `after_cursor` with newer ones, as
 *  `ConversationMessagesRequest` cursors; none means that side is done.
 */
export type MessageWindow = {
	items: TimelineMessage[],
	before_cursor: string | null,
	after_cursor: string | null,
};

/**
 *  What a delete-after did: it removed the messages the selected branch
 *  owns after the message, or, when some of them belong to the branch it
 *  came from, forked a new branch at the message, selected it and deleted
 *  nothing.
 */
export type MessagesDeleteAfterOutcome = { type: "tombstoned"; removed: string[] } | { type: "branched"; branch_id: string };

/**  The outcome of a delete-after and the conversation revision it left. */
export type MessagesDeleteAfterResult = {
	outcome: MessagesDeleteAfterOutcome,
	revision: number,
};

/**
 *  The messages a delete removed from the chat and the conversation
 *  revision it left.
 */
export type MessagesDeleted = {
	message_ids: string[],
	revision: number,
};

export type ParticipantRole = "user" | "character" | "system";

/**  A group participant as the chat uses it now. */
export type ParticipantSettings = {
	participant_id: string,
	character_id: string | null,
	name: string,
	enabled: boolean,
	muted: boolean,
	/**  The member's own model; none follows the character's default model. */
	model: SettingChoice,
};

export type ParticipantView = {
	id: string,
	role: ParticipantRole,
	name: string,
	character_id: string | null,
	avatar: AssetRef | null,
};

export type PurgeNoticeDismissRequest = {
	id: string,
};

export type PurgeNoticeEntityDto = "conversation" | "character" | "group" | "database_file" | "media_asset" | "sync_entity";

export type PurgeNoticeList = {
	items: PurgeNoticeView[],
};

export type PurgeNoticeReasonDto = "kept_unsent_local_changes" | "rejournal_incomplete" | "rejournal_dropped" | "dropped_after_failures" | "group_below_two_members" | "media_collection_skipped" | "not_synced" | "conflict_carried";

/**
 *  A delete that needs the user's attention; `entity_id` names the entity
 *  (a database file name for `database_file`).
 */
export type PurgeNoticeView = {
	id: string,
	entity: PurgeNoticeEntityDto,
	entity_id: string,
	reason: PurgeNoticeReasonDto,
	recorded_at: number,
};

/**
 *  An optional model some chats need: the embedding model for dynamic
 *  memory, the emotion model (Lettuce Thymos) for companion chats.
 */
export type RequiredModel = "embedding" | "emotion";

/**  A message whose shown text contains the query, ignoring case. */
export type SearchHit = {
	message_id: string,
	role: MessageRole,
	/**  The speaker in a group chat. */
	author_participant_id: string | null,
	text: string,
	created_at: number,
};

/**  Search hits oldest first; `next_cursor` continues with later hits. */
export type SearchHitPage = {
	items: SearchHit[],
	next_cursor: string | null,
};

export type SendAccepted = {
	user_message_id: string,
	turn_id: string,
};

/**
 *  The background the chat shows: an image, hidden, or (neither) whatever
 *  the scene, character or group shows.
 */
export type SettingBackground = {
	asset: AssetRef | null,
	hidden: boolean,
	source: SettingSource,
};

export type SettingChatMode = {
	mode: GroupChatMode,
	source: SettingSource,
};

/**  A setting that names one source; `id` is none when the setting is off. */
export type SettingChoice = {
	id: string | null,
	source: SettingSource,
};

export type SettingChoices = {
	ids: string[],
	source: SettingSource,
};

export type SettingFlag = {
	value: boolean,
	source: SettingSource,
};

export type SettingMemory = {
	mode: MemoryMode,
	source: SettingSource,
};

/**
 *  Where a setting's current value comes from: the conversation's own
 *  choice (which the user can reset), its group, its character, its launch,
 *  or the app default.
 */
export type SettingSource = "conversation" | "group" | "character" | "launch" | "app_default";

export type SettingSpeakerSelection = {
	method: SpeakerSelectionMethod,
	source: SettingSource,
};

export type SpeakerSelectionChange = { type: "set"; method: SpeakerSelectionMethod } | { type: "reset" };

export type SpeakerSelectionMethod = "llm" | "heuristic" | "round_robin" | "director" | "director_action";

export type TimelineMessage = {
	id: string,
	role: MessageRole,
	author_participant_id: string | null,
	parts: MessagePartView[],
	reasoning: string | null,
	created_at: number,
	/**  The shown reply variant's ordinal; set on generated replies only. */
	candidate_index: number | null,
	candidate_count: number,
	pinned: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}
